window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-504e6c2cf62a0025"]={"versions": [{"id": "FIG-504e6c2cf62a0025", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition von Modelländerungen bei Referenzen zwischen identifizierbaren AUTOSAR-Metaklassen im Kontext des AUTOSAR-Modellaustauschs und der Werkzeug-Interoperabilität (AUTOSAR_TR_InteroperabilityOfAutosarTools, Kapitel 3.2.1.4).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt zwei UML-Klassen:</p>\n<ul class=\"fig-list\"><li>Metaklasse <code>A</code> (Stereotyp bzw. Eigenschaft <code>Identifiable</code>, farblich hervorgehoben in Gelb/Orange), dargestellt mit getrenntem Namens- und unterem Fach.\n</li><li>Metaklasse <code>C</code> (Stereotyp bzw. Eigenschaft <code>Identifiable</code>, hell hinterlegt), ebenfalls mit getrenntem Namens- und unterem Fach.\n</li><li>Eine gerichtete Assoziation / Referenz (durchgezogene Linie mit offener Pfeilspitze) von <code>A</code> nach <code>C</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Diagramm ohne dynamische Sequenzabläufe. Die gerichtete Beziehung verdeutlicht den Abhängigkeitspfad für die Änderungsdetektion: Eine Instanz von <code>A</code> referenziert eine Instanz von <code>C</code>. Ändert sich das Zielobjekt <code>C</code> inhaltlich, gilt <code>A</code> als unverändert; ändert sich jedoch der <code>shortName</code> von <code>C</code> oder wird die Referenzbeziehung selbst hinzugefügt, entfernt oder umgebogen, gilt <code>A</code> als modifiziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevant für AUTOSAR-Autorentools, Modellvergleichs- und Merge-Algorithmen. Identifizierbare Metaklassen besitzen einen <code>shortName</code>. Referenzen werden intern über diesen Pfad/Namen aufgelöst. Entwickler von Modellvergleichs-Tools müssen beachten, dass die Aktualisierung des Referenzstrings in <code>A</code> (infolge einer Umbenennung von <code>C</code>) als Modifikation von <code>A</code> gewertet werden muss, während reine Attributänderungen am Zielobjekt <code>C</code> keinen Änderungsstatus an <code>A</code> auslösen.</p>"}, {"id": "FIG-db67a26c81259260", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition von Modelländerungen bei Referenzen zwischen identifizierbaren AUTOSAR-Metaklassen im Kontext des AUTOSAR-Modellaustauschs und der Werkzeug-Interoperabilität (AUTOSAR_TR_InteroperabilityOfAutosarTools, Kapitel 3.2.1.4).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt zwei UML-Klassen:</p>\n<ul class=\"fig-list\"><li>Metaklasse <code>A</code> (Stereotyp bzw. Eigenschaft <code>Identifiable</code>, gelb/orange hinterlegt), dargestellt als ungeteiltes Klassenelement ohne horizontale Trennlinie zum Attributfach.\n</li><li>Metaklasse <code>C</code> (Stereotyp bzw. Eigenschaft <code>Identifiable</code>, hell hinterlegt), dargestellt als ungeteiltes Klassenelement ohne horizontale Trennlinie zum Attributfach.\n</li><li>Eine gerichtete Assoziation / Referenz (durchgezogene Linie mit offener Pfeilspitze) von <code>A</code> nach <code>C</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Diagramm ohne dynamische Sequenzabläufe. Die gerichtete Beziehung verdeutlicht den Abhängigkeitspfad für die Änderungsdetektion: Eine Instanz von <code>A</code> referenziert eine Instanz von <code>C</code>. Ändert sich das Zielobjekt <code>C</code> inhaltlich, gilt <code>A</code> als unverändert; ändert sich jedoch der <code>shortName</code> von <code>C</code> oder wird die Referenzbeziehung selbst hinzugefügt, entfernt oder umgebogen, gilt <code>A</code> als modifiziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevant für AUTOSAR-Autorentools, Modellvergleichs- und Merge-Algorithmen. Identifizierbare Metaklassen besitzen einen <code>shortName</code>. Referenzen werden intern über diesen Pfad/Namen aufgelöst. Entwickler von Modellvergleichs-Tools müssen beachten, dass die Aktualisierung des Referenzstrings in <code>A</code> (infolge einer Umbenennung von <code>C</code>) als Modifikation von <code>A</code> gewertet werden muss, während reine Attributänderungen am Zielobjekt <code>C</code> keinen Änderungsstatus an <code>A</code> auslösen.</p>"}], "trans": [{"from": "FIG-504e6c2cf62a0025", "to": "FIG-db67a26c81259260", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>UML-Klassen <code>A</code> und <code>C</code>: Die horizontale Trennlinie zwischen dem Namensbereich und dem Attributfach ist entfallen; die Klassenboxen werden jeweils als ungeteilte Rechtecke dargestellt.\n</li></ul>"}]};
